import heapq

def top_tags(tags, k):
    counts = {}
    for t in tags:
        counts[t] = counts.get(t, 0) + 1
    heap = []
    for tag, c in counts.items():
        heapq.heappush(heap, (c, tag))
        if len(heap) > k:
            heapq.heappop(heap)
    return [tag for _, tag in heap]

