function top_tags(tags, k) {
  const counts = new Map();
  for (const t of tags) counts.set(t, (counts.get(t) || 0) + 1);
  const buckets = Array.from({ length: tags.length + 1 }, () => []);
  for (const [tag, c] of counts) buckets[c].push(tag);
  const out = [];
  for (let c = buckets.length - 1; c >= 0 && out.length < k; c--) {
    for (const tag of buckets[c]) {
      if (out.length < k) out.push(tag);
    }
  }
  return out;
}

