import java.util.*;

class Solution {
    public List<String> topTags(String[] tags, int k) {
        Map<String, Integer> counts = new HashMap<>();
        for (String t : tags) counts.put(t, counts.getOrDefault(t, 0) + 1);
        // A min-heap of the k most used: the least used (then alphabetically first) leaves first.
        PriorityQueue<String> heap = new PriorityQueue<>((a, b) -> {
            int byCount = Integer.compare(counts.get(a), counts.get(b));
            return byCount != 0 ? byCount : a.compareTo(b);
        });
        for (String tag : counts.keySet()) {
            heap.add(tag);
            if (heap.size() > k) heap.poll();
        }
        return new ArrayList<>(heap);
    }
}

